    const node = {
      onaudioprocess: null,
      connect() {
        ctx.timer = setInterval(() => {
          const frame = new Float32Array(size);
          frame.set(input.subarray(inputOffset, inputOffset + size));
          inputOffset += size;
          framesSent++;
          node.onaudioprocess?.({ inputBuffer: { getChannelData: () => frame } });
        }, (size / RATE) * 1000);
      },
      disconnect() { clearInterval(ctx.timer); },
    };
    return node;
  }
  createBuffer(_channels, length, rate) {
    const data = new Float32Array(length);
    return { duration: length / rate, getChannelData: () => data };
  }
  createBufferSource() {
    const ctx = this;
    const src = {
      buffer: null, onended: null,
      connect() {}, disconnect() {}, stop() { clearTimeout(src.t); },
      start(at) {
        output.push(src.buffer.getChannelData(0));
        src.t = setTimeout(() => src.onended?.(),
          Math.max(0, (at - ctx.currentTime + src.buffer.duration) * 1000));
      },
    };
    return src;
  }
}
globalThis.AudioContext = FakeAudioContext;
const track = { enabled: true, muted: false, readyState: 'live',
  stop() { this.readyState = 'ended'; }, addEventListener() {}, removeEventListener() {} };
Object.defineProperty(globalThis, 'navigator', { configurable: true, value: {
  mediaDevices: { getUserMedia: async () => ({ getAudioTracks: () => [track], getTracks: () => [track] }) },
} });

// --- Browser side: the public Gateway Live model + the core continuous session.
class Session extends Experimental_AbstractRealtimeSession {
  get snapshot() { return this.state; }
  setState() {}
}
const model = createGateway().experimental_realtime(MODEL, API ? { api: API } : undefined);
log('model', model.provider, model.modelId, JSON.stringify(model.capabilities));
const counts = {};
let assistant = '';
let user = '';
let lastOutputAt = 0;
let started = false;
const session = new Session({
  model,
  api: { token: tokenUrl },
  sessionConfig: { instructions: 'Answer in one short sentence.' },
  ...(API === 'realtime' ? {} : { maxPlaybackBufferSeconds: 60 }),
  onError: error => log('onError', error.message),
  onEvent: event => {
    counts[event.type] = (counts[event.type] ?? 0) + 1;
    if (event.type === 'session-started') { started = true; log('session-started', event.sessionId, event.delegationMode); }
    if (event.type === 'transcript-fragment') {
      if (event.speaker === 'assistant') { assistant += event.delta; lastOutputAt = performance.now(); }
      else user += event.delta;
    }
    if (event.type === 'session-usage' || event.type === 'session-closed')
      log(event.type, JSON.stringify(event.usage), event.reason ?? '');
    if (event.type === 'error') log('error event', event.code, event.message);
  },
});
const timeout = setTimeout(() => { log('TIMEOUT', counts, { user, assistant }); process.exit(1); }, 60_000);
await session.connect();
log('mint request body', mintBody);
await new Promise(resolve => {
  const timer = setInterval(() => {
    const inputDone = inputOffset >= input.length;
    if (started && inputDone && assistant && performance.now() - lastOutputAt > 4000) {
      clearInterval(timer); resolve();
    }
    if (session.snapshot.status === 'error') { clearInterval(timer); resolve(); }
  }, 250);
});
log('reply finished; closing');
await session.close().catch(error => log('close', error.message));
clearTimeout(timeout);
const s = session.snapshot;
const outSamples = output.reduce((n, a) => n + a.length, 0);
console.log(JSON.stringify({
  status: s.status,
  session: { usage: s.session?.usage, finalization: s.session?.finalization },
  inputSecondsSent: +(framesSent * 1024 / RATE).toFixed(2),
  speechInputSeconds: +(input.length / RATE).toFixed(2),
  outputAudioSeconds: +(outSamples / RATE).toFixed(2),
  userTranscript: user.trim(),
  assistantTranscript: assistant.trim(),
  eventCounts: counts,
}, null, 2));
// Save the spoken reply as WAV for listening.
const pcmOut = Buffer.alloc(outSamples * 2);
let o = 0;
for (const a of output) for (const v of a) { pcmOut.writeInt16LE(Math.max(-1, Math.min(1, v)) * 32767 | 0, o); o += 2; }
const header = Buffer.alloc(44);
header.write('RIFF', 0); header.writeUInt32LE(36 + pcmOut.length, 4); header.write('WAVE', 8);
header.write('fmt ', 12); header.writeUInt32LE(16, 16); header.writeUInt16LE(1, 20); header.writeUInt16LE(1, 22);
header.writeUInt32LE(RATE, 24); header.writeUInt32LE(RATE * 2, 28); header.writeUInt16LE(2, 32); header.writeUInt16LE(16, 34);
header.write('data', 36); header.writeUInt32LE(pcmOut.length, 40);
writeFileSync('/tmp/gateway-live/reply.wav', Buffer.concat([header, pcmOut]));
server.close();
process.exit(s.status === 'disconnected' && s.session?.finalization === 'confirmed' ? 0 : 1);
